-- AF-05 group governance. Join and invitation records are RLS-protected and
-- all mutation paths verify membership/manager status in the database.
alter table public.conversations add column if not exists visibility text not null default 'public';
alter table public.conversations drop constraint if exists conversations_visibility_check; alter table public.conversations add constraint conversations_visibility_check check(visibility in ('public','private','restricted'));
create table if not exists public.conversation_join_requests(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,requested_by_user_id uuid not null references auth.users(id) on delete cascade,reason text,status text not null default 'pending' check(status in ('pending','approved','rejected','cancelled')),reviewed_by_user_id uuid references auth.users(id) on delete set null,review_reason text,created_at timestamptz not null default now(),reviewed_at timestamptz,unique(conversation_id,user_id));
create table if not exists public.conversation_invitations(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,invited_user_id uuid not null references auth.users(id) on delete cascade,invited_by_user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in ('member','moderator')),message text,status text not null default 'pending' check(status in ('pending','accepted','declined','cancelled','expired')),created_at timestamptz not null default now(),responded_at timestamptz,unique(conversation_id,invited_user_id));
create index if not exists conversation_join_requests_manager_idx on public.conversation_join_requests(conversation_id,status,created_at);create index if not exists conversation_join_requests_user_idx on public.conversation_join_requests(user_id,status,created_at desc);create index if not exists conversation_invitations_manager_idx on public.conversation_invitations(conversation_id,status,created_at desc);create index if not exists conversation_invitations_user_idx on public.conversation_invitations(invited_user_id,status,created_at desc);
alter table public.conversation_join_requests enable row level security;alter table public.conversation_invitations enable row level security;grant select on public.conversation_join_requests,public.conversation_invitations to authenticated;
drop policy if exists "group managers and requesters read join requests" on public.conversation_join_requests;create policy "group managers and requesters read join requests" on public.conversation_join_requests for select to authenticated using(user_id=(select auth.uid()) or requested_by_user_id=(select auth.uid()) or public.user_can_manage_conversation(conversation_id));
drop policy if exists "group managers and invitees read invitations" on public.conversation_invitations;create policy "group managers and invitees read invitations" on public.conversation_invitations for select to authenticated using(invited_user_id=(select auth.uid()) or public.user_can_manage_conversation(conversation_id));
create or replace function public.fn_conversation_is_group(p_conversation_id uuid) returns boolean language sql stable security definer set search_path to 'public' as $$select exists(select 1 from public.conversations c where c.id=p_conversation_id and coalesce(c.is_group,false)=true and coalesce(c.is_deleted,false)=false)$$;
create or replace function public.fn_conversation_has_capacity(p_conversation_id uuid) returns boolean language sql stable security definer set search_path to 'public' as $$select coalesce(c.max_members,2147483647)>(select count(*) from public.conversation_members m where m.conversation_id=c.id and m.left_at is null) from public.conversations c where c.id=p_conversation_id$$;
create or replace function public.fn_invite_to_conversation(p_conversation_id uuid,p_invited_user_id uuid,p_role text default 'member',p_message text default null) returns jsonb language plpgsql security definer set search_path to 'public' as $$declare v_me uuid:=auth.uid();v_id uuid;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if p_role not in ('member','moderator')or not public.fn_conversation_is_group(p_conversation_id)or not public.user_can_manage_conversation(p_conversation_id)then raise exception 'Not authorized' using errcode='42501';end if;if not exists(select 1 from auth.users where id=p_invited_user_id)or exists(select 1 from public.conversation_members where conversation_id=p_conversation_id and user_id=p_invited_user_id and left_at is null)then raise exception 'User is unavailable' using errcode='22023';end if;insert into public.conversation_invitations(conversation_id,invited_user_id,invited_by_user_id,role,message,status)values(p_conversation_id,p_invited_user_id,v_me,p_role,nullif(trim(p_message),''),'pending')on conflict(conversation_id,invited_user_id)do update set invited_by_user_id=excluded.invited_by_user_id,role=excluded.role,message=excluded.message,status='pending',responded_at=null,created_at=now()returning id into v_id;return jsonb_build_object('ok',true,'id',v_id);end $$;
create or replace function public.fn_review_join_request(p_request_id uuid,p_approve boolean,p_reason text default null) returns jsonb language plpgsql security definer set search_path to 'public' as $$declare v_me uuid:=auth.uid();v public.conversation_join_requests%rowtype;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;select * into v from public.conversation_join_requests where id=p_request_id for update;if not found or v.status<>'pending'or not public.user_can_manage_conversation(v.conversation_id)then raise exception 'Not authorized' using errcode='42501';end if;if p_approve and not public.fn_conversation_has_capacity(v.conversation_id)then raise exception 'This group is full' using errcode='22023';end if;update public.conversation_join_requests set status=case when p_approve then 'approved' else 'rejected'end,reviewed_by_user_id=v_me,review_reason=nullif(trim(p_reason),''),reviewed_at=now()where id=v.id;if p_approve then insert into public.conversation_members(conversation_id,user_id,role,joined_at,left_at)values(v.conversation_id,v.user_id,'member',now(),null)on conflict(conversation_id,user_id)do update set role='member',joined_at=now(),left_at=null;end if;return jsonb_build_object('ok',true,'approved',p_approve);end $$;
create or replace function public.fn_set_group_avatar(p_conversation_id uuid,p_avatar_url text) returns jsonb language plpgsql security definer set search_path to 'public' as $$begin if auth.uid()is null or not public.fn_conversation_is_group(p_conversation_id)or not public.user_can_manage_conversation(p_conversation_id)then raise exception 'Not authorized' using errcode='42501';end if;update public.conversations set avatar_url=nullif(trim(p_avatar_url),''),updated_at=now()where id=p_conversation_id;return jsonb_build_object('ok',true);end $$;
create or replace function public.fn_request_add_member(p_conversation_id uuid,p_user_id uuid,p_message text default null) returns jsonb language plpgsql security definer set search_path to 'public' as $$declare v_me uuid:=auth.uid();v_manager boolean;v_id uuid;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if not public.fn_conversation_is_group(p_conversation_id)or not exists(select 1 from public.conversation_members where conversation_id=p_conversation_id and user_id=v_me and left_at is null)then raise exception 'Not authorized' using errcode='42501';end if;if not exists(select 1 from auth.users where id=p_user_id)or exists(select 1 from public.conversation_members where conversation_id=p_conversation_id and user_id=p_user_id and left_at is null)then raise exception 'User is unavailable' using errcode='22023';end if;v_manager:=public.user_can_manage_conversation(p_conversation_id);if v_manager then if not public.fn_conversation_has_capacity(p_conversation_id)then raise exception 'This group is full' using errcode='22023';end if;insert into public.conversation_members(conversation_id,user_id,role,joined_at,left_at)values(p_conversation_id,p_user_id,'member',now(),null)on conflict(conversation_id,user_id)do update set role='member',joined_at=now(),left_at=null;return jsonb_build_object('ok',true,'status','added');end if;insert into public.conversation_join_requests(conversation_id,user_id,requested_by_user_id,reason,status)values(p_conversation_id,p_user_id,v_me,nullif(trim(p_message),''),'pending')on conflict(conversation_id,user_id)do update set requested_by_user_id=excluded.requested_by_user_id,reason=excluded.reason,status='pending',reviewed_by_user_id=null,review_reason=null,reviewed_at=null,created_at=now()returning id into v_id;return jsonb_build_object('ok',true,'status','pending','id',v_id);end $$;
create or replace function public.fn_request_join(p_conversation_id uuid,p_message text default null) returns jsonb language plpgsql security definer set search_path to 'public' as $$declare v_me uuid:=auth.uid();v_visibility text;v_id uuid;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;select visibility into v_visibility from public.conversations where id=p_conversation_id and coalesce(is_group,false)=true and coalesce(is_deleted,false)=false;if v_visibility is null then raise exception 'Group not found' using errcode='P0002';end if;if exists(select 1 from public.conversation_members where conversation_id=p_conversation_id and user_id=v_me and left_at is null)then return jsonb_build_object('ok',true,'status','member');end if;if v_visibility='private'then raise exception 'This group requires an invitation' using errcode='42501';end if;if v_visibility='public'then if not public.fn_conversation_has_capacity(p_conversation_id)then raise exception 'This group is full' using errcode='22023';end if;insert into public.conversation_members(conversation_id,user_id,role,joined_at,left_at)values(p_conversation_id,v_me,'member',now(),null)on conflict(conversation_id,user_id)do update set role='member',joined_at=now(),left_at=null;return jsonb_build_object('ok',true,'status','added');end if;insert into public.conversation_join_requests(conversation_id,user_id,requested_by_user_id,reason,status)values(p_conversation_id,v_me,v_me,nullif(trim(p_message),''),'pending')on conflict(conversation_id,user_id)do update set reason=excluded.reason,status='pending',reviewed_by_user_id=null,review_reason=null,reviewed_at=null,created_at=now()returning id into v_id;return jsonb_build_object('ok',true,'status','pending','id',v_id);end $$;
create or replace function public.fn_respond_invitation(p_invitation_id uuid,p_accept boolean) returns jsonb language plpgsql security definer set search_path to 'public' as $$declare v_me uuid:=auth.uid();v public.conversation_invitations%rowtype;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;select * into v from public.conversation_invitations where id=p_invitation_id and invited_user_id=v_me for update;if not found or v.status<>'pending'then raise exception 'Invitation not found' using errcode='P0002';end if;if p_accept then if not public.fn_conversation_has_capacity(v.conversation_id)then raise exception 'This group is full' using errcode='22023';end if;insert into public.conversation_members(conversation_id,user_id,role,joined_at,left_at)values(v.conversation_id,v_me,v.role,now(),null)on conflict(conversation_id,user_id)do update set role=excluded.role,joined_at=now(),left_at=null;end if;update public.conversation_invitations set status=case when p_accept then 'accepted'else 'declined'end,responded_at=now()where id=v.id;return jsonb_build_object('ok',true,'accepted',p_accept,'conversation_id',v.conversation_id);end $$;
revoke all on function public.fn_conversation_is_group(uuid),public.fn_conversation_has_capacity(uuid),public.fn_invite_to_conversation(uuid,uuid,text,text),public.fn_review_join_request(uuid,boolean,text),public.fn_set_group_avatar(uuid,text),public.fn_request_add_member(uuid,uuid,text),public.fn_request_join(uuid,text),public.fn_respond_invitation(uuid,boolean) from public,anon;
grant execute on function public.fn_invite_to_conversation(uuid,uuid,text,text),public.fn_review_join_request(uuid,boolean,text),public.fn_set_group_avatar(uuid,text),public.fn_request_add_member(uuid,uuid,text),public.fn_request_join(uuid,text),public.fn_respond_invitation(uuid,boolean) to authenticated,service_role;
notify pgrst,'reload schema';
